"""Render ``evals/answers.md`` and the row level Parquet from a run. Do not edit the output by
hand.

    uv run python -m evals.answers.render --run 2026-11-23

Layout, in the order a reader needs it: the judge's agreement rate first (every groundedness
figure depends on it); then one table per set, each row one arm on one split, carrying n, the
test evaluation count, both failure directions as counts, the refusal pair together, citation
validity as a violation count, groundedness beside the agreement rate, and cost and latency;
then the ablations, retrieval and answer metrics side by side in one row per arm; then the
retry arm's cost against the refusals it recovered; then spend, estimated against actual.
"""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

from evals.answers import judge as judge_mod
from evals.answers.metrics import (
    Agreement,
    CitationCheck,
    citation_validity,
    gold_check,
    groundedness,
    recall_any_version_at,
    recall_at,
    refusal_pair,
    spread,
)
from evals.answers.run import ARMS, EVAL_TODAY, RUNS
from evals.answers.sets import REMOVED
from evals.metrics import Estimate
from evals.retrieval import read_counter

OUT = Path(__file__).resolve().parents[1] / "answers.md"
RESULTS = Path(__file__).resolve().parent / "results"
SETS = ("answerable", "as_of", "unanswerable")


def _est(e: Estimate, digits: int = 2) -> str:
    if e.value is None:
        return "-"
    return f"{e.value:.{digits}f} [{e.low:.{digits}f}, {e.high:.{digits}f}]"


def _count(k: int, n: int) -> str:
    return f"{k}/{n}"


def _eur(v: float | None) -> str:
    return "-" if v is None else f"{v:.4f}"


def _ms(v: float | None) -> str:
    return "-" if v is None else f"{v / 1000:.1f} s"


def _agreement_text(a: Agreement | None) -> str:
    if a is None:
        return "awaiting hand labels"
    kappa = "" if a.kappa is None else f", kappa {a.kappa:.2f}"
    return f"{a.agree}/{a.n} = {_est(a.rate)}{kappa}"


def _ground(verdicts: Sequence[bool], a: Agreement | None) -> str:
    if not verdicts:
        return "-"
    if a is None:
        # The order is the rule: no groundedness figure before the judge's own agreement.
        return f"withheld until the hand labels are in ({len(verdicts)} claims judged)"
    g = groundedness(verdicts, a)
    # Stated at the precision the judge supports: one decimal until agreement is known.
    digits = 2 if a is not None and a.rate.low is not None and a.rate.low >= 0.9 else 1
    return (
        f"{g.supported}/{g.judged} = {_est(g.rate, digits)} (judge agreement {_agreement_text(a)})"
    )


def _stopped(summary: Mapping[str, Any]) -> str:
    return f"stopped: {summary['stopped']}" if summary.get("stopped") else "finished under it"


def _select(rows: Sequence[Mapping[str, Any]], **kw: str) -> list[Mapping[str, Any]]:
    return [r for r in rows if all(r[k] == v for k, v in kw.items())]


def render(
    run: str,
    rows: Sequence[Mapping[str, Any]],
    judged: Sequence[Mapping[str, Any]],
    a: Agreement | None,
    citations: Mapping[tuple[str, str, str], CitationCheck],
    summary: Mapping[str, Any],
    counter: Mapping[str, int],
    by_arm: Mapping[str, CitationCheck],
) -> str:
    verdicts: dict[tuple[str, str, str], list[bool]] = {}
    for j in judged:
        verdicts.setdefault((j["arm"], j["set"], j["split"]), []).append(bool(j["supported"]))
    arms = [x for x in ARMS if any(r["arm"] == x for r in rows)]
    splits = [s for s in ("dev", "test") if any(r["split"] == s for r in rows)]
    lines = [
        "# Answer level evaluation",
        "",
        "Generated by `python -m evals.answers.render` from the run's row level results; do not"
        " edit by hand. Row level Parquet is in `evals/answers/results/`.",
        "",
        f"- Run `{run}` on build `{summary.get('schema')}`, every question asked as of its own"
        f" date with today taken as {EVAL_TODAY.isoformat()}.",
        "- Sets, never pooled: `answerable` (questions written from sampled in-force paragraphs,"
        " the gold known by construction; this replaces the FAQ derived set), `as_of` (five"
        " amended provisions, each asked on both sides of the change) and `unanswerable` (ten"
        " each: absent topics, entity types with no provision, dates before the governing"
        " instrument, provisions repealed by the date asked). See `evals/answers/sets/`.",
        f"- Removed from the unanswerable set after the run, as answerable after all:"
        f" {len(REMOVED)} of 40, each found because the system answered it or nearly did: "
        + "; ".join(f"`{q}`, {why}" for q, why in REMOVED.items())
        + ".",
        "- Test half evaluations so far: "
        + ", ".join(f"{s} {counter.get('answers:' + s, 0)}" for s in SETS)
        + ".",
        f"- Spend: estimated EUR {summary.get('estimate_eur', 0):.2f} by the dry run, actual"
        f" EUR {summary.get('spend_eur', 0) + summary.get('judge_pass_eur', 0):.2f}: EUR"
        f" {summary.get('spend_eur', 0):.2f} for the arms over {summary.get('fresh_calls', 0)}"
        f" new model and embedding calls, and EUR {summary.get('judge_pass_eur', 0):.2f} for the"
        f" judge pass over {summary.get('judge_pass_calls', 0)} new calls. Every other call was"
        " replayed from a cassette. The run was capped at EUR"
        f" {summary.get('budget_eur', 0):.2f} and {_stopped(summary)}.",
        "- Intervals are 95% seeded bootstrap intervals. Counts come first: a rate on a few dozen"
        " questions hides how few events it describes.",
        "",
        "## The judge's agreement with a person",
        "",
        f"Measured before any groundedness figure is read: {_agreement_text(a)}. Every"
        " groundedness figure below carries it in the same cell.",
        "",
    ]
    for name in SETS:
        lines += [f"## {name}", ""]
        header = (
            "| Arm | Split | n | Answered | Gold cited | Wrong answers | Wrong refusals |"
            " Refusal pair (correct refusals on unanswerable; false refusals here) |"
            " Citation violations | Groundedness | Cost p50 / p95 (EUR) | Latency p50 / p95 |"
        )
        if name == "unanswerable":
            header = (
                "| Arm | Split | n | Refused | Refused for the expected reason | Wrong answers |"
                " Refusal pair (correct refusals here; false refusals on answerable) |"
                " Citation violations | Groundedness | Cost p50 / p95 (EUR) | Latency p50 / p95 |"
            )
        lines += [header, "|" + "---|" * (header.count("|") - 1)]
        for arm in arms:
            for split in splits:
                rs = _select(rows, arm=arm, set=name, split=split)
                if not rs:
                    continue
                ans = _select(rows, arm=arm, set="answerable", split=split)
                una = _select(rows, arm=arm, set="unanswerable", split=split)
                pair = refusal_pair(ans + _select(rows, arm=arm, set="as_of", split=split), una)
                pair_text = (
                    f"{_count(pair.refused, pair.unanswerable)} = {_est(pair.correctness)};"
                    f" {_count(pair.false_refusals, pair.answerable)}"
                    f" = {_est(pair.false_refusal_rate)}"
                )
                cit = citations[(arm, name, split)]
                cit_text = f"{cit.violations} of {cit.citations}" + (
                    f" (quotes not in the text: {cit.quote_violations})"
                    if cit.quote_violations
                    else ""
                )
                cost = spread([r["cost_eur"] for r in rs])
                lat = spread([r["latency_ms"] for r in rs])
                ground = _ground(verdicts.get((arm, name, split), []), a)
                count = f"{counter.get('answers:' + name, 0)}" if split == "test" else "-"
                answered = sum(r["outcome"] == "answer" for r in rs)
                if name == "unanswerable":
                    refused = sum(r["outcome"] == "refusal" for r in rs)
                    expected = sum(
                        r["outcome"] == "refusal" and r["reason"] == r["expect"] for r in rs
                    )
                    lines.append(
                        f"| {arm} | {split} | {len(rs)} (test evals {count}) | {refused} |"
                        f" {expected} |"
                        f" {answered} | {pair_text} | {cit_text} | {ground} |"
                        f" {_eur(cost.p50)} / {_eur(cost.p95)} | {_ms(lat.p50)} / {_ms(lat.p95)} |"
                    )
                else:
                    g = gold_check(rs)
                    wrong = g.other_cited + (g.wrong_version if name == "as_of" else 0)
                    refused = sum(r["outcome"] != "answer" for r in rs)
                    lines.append(
                        f"| {arm} | {split} | {len(rs)} (test evals {count}) | {answered} |"
                        f" {g.gold_cited} = {_est(g.accuracy)} | {wrong} | {refused} |"
                        f" {pair_text} | {cit_text} | {ground} |"
                        f" {_eur(cost.p50)} / {_eur(cost.p95)} | {_ms(lat.p50)} / {_ms(lat.p95)} |"
                    )
        lines.append("")
        lines += _notes(name)
    lines += _ablations(rows, arms, by_arm)
    lines += _retry(rows)
    return "\n".join(lines) + "\n"


def _notes(name: str) -> list[str]:
    if name == "answerable":
        return [
            "Wrong answers here are answers that cite only paragraphs other than the gold: not"
            " proven wrong, never proven right. Wrong refusals are answerable questions refused"
            " (or shown retrieval only).",
            "",
        ]
    if name == "as_of":
        return [
            "Wrong answers here include answers citing a version of the provision not in force"
            " on the date asked.",
            "",
        ]
    return [
        "Wrong answers here are unanswerable questions answered. The expected reason is the"
        " refusal the question was built for; another refusal still counts as correct.",
        "",
    ]


def _ablations(
    rows: Sequence[Mapping[str, Any]], arms: Sequence[str], by_arm: Mapping[str, CitationCheck]
) -> list[str]:
    lines = [
        "## Ablations: retrieval and answers side by side",
        "",
        "Both splits together, per arm. Retrieval is recall at 10 of the gold paragraph among the"
        " candidates the arm ranked: the exact version in force on the date asked, and, for"
        " as_of, any version of it. The answer columns are what the arm then did with them.",
        "",
        "| Arm | Recall@10, answerable | Recall@10, as_of | Recall@10 any version, as_of"
        " | Gold cited, as_of"
        " | Cited a version not in force, as_of | Gold cited, answerable | Citation violations"
        " | Quotes not in the text | Wrong refusals | Correct refusals | Cost p50 (EUR) |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for arm in arms:
        ans, aso, una = (_select(rows, arm=arm, set=s) for s in SETS)
        ga, go = gold_check(ans), gold_check(aso)
        pair = refusal_pair(ans + aso, una)
        cit = by_arm[arm]
        costs = [r["cost_eur"] for r in rows if r["arm"] == arm]
        lines.append(
            f"| {arm} | {_est(recall_at(ans, 10))} | {_est(recall_at(aso, 10))} |"
            f" {_est(recall_any_version_at(aso, 10))} |"
            f" {go.gold_cited}/{len(aso)} | {go.wrong_version} | {ga.gold_cited}/{len(ans)} |"
            f" {cit.violations} of {cit.citations} | {cit.quote_violations} |"
            f" {pair.false_refusals}/{pair.answerable} |"
            f" {pair.refused}/{pair.unanswerable} | {_eur(spread(costs).p50)} |"
        )
    return [*lines, ""]


def _retry(rows: Sequence[Mapping[str, Any]]) -> list[str]:
    base = {r["qid"]: r for r in rows if r["arm"] == "baseline"}
    retry = [r for r in rows if r["arm"] == "retry"]
    if not retry:
        return []
    tried = [r for r in retry if r["retried"]]
    recovered = [r for r in tried if r["retry_recovered"]]
    answerable = [r for r in retry if r["set"] != "unanswerable"]
    fr_base = sum(base[r["qid"]]["outcome"] != "answer" for r in answerable if r["qid"] in base)
    fr_retry = sum(r["outcome"] != "answer" for r in answerable)
    extra = [r["cost_eur"] - base[r["qid"]]["cost_eur"] for r in tried if r["qid"] in base]
    mean_extra = sum(extra) / len(extra) if extra else 0.0
    total_extra = sum(extra)
    return [
        "## The retry arm",
        "",
        f"- Verification failures retried: {len(tried)}; recovered into an answer:"
        f" {len(recovered)}.",
        f"- Wrong refusals on answerable and as_of questions: baseline {fr_base}, with retry"
        f" {fr_retry}, of {len(answerable)}.",
        f"- Extra cost: EUR {total_extra:.4f} in all, EUR {mean_extra:.4f} per retried question"
        " (one more composer call).",
        "",
    ]


def to_parquet(rows: Sequence[Mapping[str, Any]], path: Path) -> Path:
    import pyarrow as pa
    import pyarrow.parquet as pq

    flat = [
        {
            k: (json.dumps(v, ensure_ascii=False) if isinstance(v, (list, dict)) else v)
            for k, v in r.items()
        }
        for r in rows
    ]
    path.parent.mkdir(parents=True, exist_ok=True)
    pq.write_table(pa.Table.from_pylist(flat), path)
    return path


def main(argv: list[str] | None = None) -> int:
    import psycopg
    from psycopg import sql

    from extant.index.settings import load_index_settings

    parser = argparse.ArgumentParser(prog="python -m evals.answers.render")
    parser.add_argument("--run", default=EVAL_TODAY.isoformat())
    args = parser.parse_args(argv)
    run_dir = RUNS / args.run
    rows = [json.loads(x) for x in (run_dir / "rows.jsonl").read_text().splitlines() if x]
    rows = [r for r in rows if r["qid"] not in REMOVED]  # mislabelled: scored in no set
    judged = (
        [json.loads(x) for x in (run_dir / "judged.jsonl").read_text().splitlines() if x]
        if (run_dir / "judged.jsonl").exists()
        else []
    )
    labels = judge_mod.LABELS / f"{EVAL_TODAY.isoformat()}.md"
    a = judge_mod.measure(labels) if labels.exists() else None
    summary = json.loads((run_dir / "summary.json").read_text())
    with psycopg.connect(load_index_settings().writer_dsn.get_secret_value()) as conn:
        conn.execute(
            sql.SQL("SET search_path TO {}, public").format(sql.Identifier(summary["schema"]))
        )
        paragraphs = {r[0] for r in conn.execute("SELECT para_id FROM paragraphs").fetchall()}
        cited = list({c["para_id"] for r in rows for cl in r["claims"] for c in cl["citations"]})
        bodies: dict[str, str] = dict(
            conn.execute(
                "SELECT para_id, body FROM paragraphs WHERE para_id = ANY(%s)", (cited,)
            ).fetchall()
        )
    citations: dict[tuple[str, str, str], CitationCheck] = {}
    by_arm: dict[str, CitationCheck] = {}
    for arm in ARMS:
        by_arm[arm] = citation_validity([r for r in rows if r["arm"] == arm], paragraphs, bodies)
        for name in SETS:
            for split in ("dev", "test"):
                sel = [r for r in rows if (r["arm"], r["set"], r["split"]) == (arm, name, split)]
                citations[(arm, name, split)] = citation_validity(sel, paragraphs, bodies)
    OUT.write_text(
        render(args.run, rows, judged, a, citations, summary, read_counter(), by_arm),
        encoding="utf-8",
    )
    to_parquet(rows, Path(__file__).resolve().parent / "results" / f"{args.run}.parquet")
    print(f"wrote {OUT}")
    for (arm, name, split), cit in citations.items():
        if cit.violations:
            print(f"CITATION VIOLATION {arm} {name} {split}: {cit.examples}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
